/**
 * engine-server/config.ts — 配置集中管理
 *
 * 所有环境变量和配置项统一从此文件导出。
 * 遵循"后端铁律"：环境变量不散落在代码各处。
 */
/** 引擎服务端口 */
export declare const ENGINE_PORT: number;
/** 引擎服务主机 */
export declare const ENGINE_HOST: string;
/**
 * Gateway 地址（ClawOrg 自身的 OpenClaw Gateway）
 *
 * ⚠️ 红线：不要指向 EasyClaw 或其他产品的 Gateway 端口。
 * ClawOrg 是独立产品，与其混用 Gateway 是设计违规。
 * 未设置时（空串或未定义），LLM client 会跳过 Gateway，直接走 DEEPSEEK_API_KEY 直连。
 */
export declare const GATEWAY_HOST: string;
/** LLM 模型 */
export declare const LLM_MODEL: string;
/** LLM 请求超时（毫秒） */
export declare const LLM_TIMEOUT_MS: number;
/** LLM max_tokens */
export declare const LLM_MAX_TOKENS: number;
/** LLM temperature */
export declare const LLM_TEMPERATURE: number;
/** 出厂 API Key（fallback）。Gateway 不可用时直连 DeepSeek。生产环境必须设置 DEEPSEEK_API_KEY 或 GATEWAY_HOST 之一。 */
export declare const DEEPSEEK_API_KEY: string;
/** API Token 前缀 */
export declare const AUTH_TOKEN_PREFIX = "Bearer ";
export declare function getValidTokens(): string[];
/** 认证失败限流：每 IP 10 次/分钟 */
export declare const RATE_LIMIT_AUTH: {
    windowMs: number;
    max: number;
};
/** 生成端点限流：每 token 20 次/小时 */
export declare const RATE_LIMIT_GENERATE: {
    windowMs: number;
    max: number;
};
/** 轮询端点限流：每 token 60 次/分钟 */
export declare const RATE_LIMIT_POLL: {
    windowMs: number;
    max: number;
};
/** 最大并发任务数 */
export declare const MAX_CONCURRENT_TASKS: number;
/** 同步模式超时（毫秒）。管道包含7次LLM调用+退化重推，实际耗时45-90s */
export declare const SYNC_TIMEOUT_MS: number;
/** 任务过期时间最小值（秒） */
export declare const TASK_TTL_MIN_SECONDS = 900;
/** 任务过期清理间隔（毫秒） */
export declare const TASK_CLEANUP_INTERVAL_MS = 60000;
/** 估算生成时间（秒） */
export declare const ESTIMATED_GENERATION_SECONDS = 45;
export declare const ENGINE_VERSION = "3.1.0";
export declare const PIPELINE_VERSION = "v0.4.0";
export declare const BLUEPRINT_SCHEMA_VERSION = "1.0";
export declare const INPUT_CONSTRAINTS: {
    readonly jobMinLength: 1;
    readonly jobMaxLength: 500;
    readonly constraintsMinCount: 1;
    readonly constraintsMaxCount: 10;
    readonly successMetricsMaxCount: 5;
    readonly failureModesMaxCount: 5;
    readonly confidenceMin: 0;
    readonly confidenceMax: 1;
    readonly supportedSchemaVersions: readonly ["1.0"];
    readonly supportedStages: readonly ["from_scratch", "expansion", "optimization"];
};
